# name: familiar_vs_plain_outlier_rule_contrast
# description: In >=3-example sets where all but one example share a final digit or a parity, yes rate for non-example targets obeying that majority rule when the lone outlier is a familiar number (1, 100, power of 2, square, 27, multiple of 10) minus when it is unremarkable; observed below null means people do not excuse familiar outliers more than plain ones as strongly as the familiar-stray model predicts, above means they excuse them even more.

def _sets(df):
    """Per row: tuple of examples (shown order). Parsed once per unique set."""
    u = pd.unique(df["number_set"].astype(str))
    parsed = {s: tuple(int(x) for x in s.split(",")) for s in u}
    return df["number_set"].astype(str).map(parsed), parsed

def _rate(r, m):
    m = np.asarray(m, dtype=bool)
    return float(r[m].mean()) if m.any() else 0.0

FAMILIAR = set([1, 100] + [2 ** k for k in range(1, 7)] + [k * k for k in range(2, 10)] + [27] + list(range(10, 100, 10)))

def test_statistic(df):
    ex, parsed = _sets(df)
    info = {}
    for s, e in parsed.items():
        info[s] = None
        n = len(e)
        if n < 3:
            continue
        for key in (lambda x: x % 10, lambda x: x % 2):
            ks = [key(x) for x in e]
            vals, cnt = np.unique(ks, return_counts=True)
            if cnt.max() == n - 1:
                maj = vals[cnt.argmax()]
                out = [x for x in e if key(x) != maj][0]
                info[s] = (key, maj, out in FAMILIAR)
                break
    t = df["target"].astype(int).to_numpy()
    r = df["rating"].astype(float).to_numpy()
    sets = df["number_set"].astype(str).to_numpy()
    obey = np.zeros(len(t), bool); fam = np.zeros(len(t), bool)
    for s in parsed:
        if info[s] is None:
            continue
        key, maj, f = info[s]
        m = (sets == s) & ~np.isin(t, parsed[s])
        ok = (t % 10 == maj) if key(13) == 3 else (t % 2 == maj)
        obey |= m & ok
        fam |= m & ok & f
    return _rate(r, obey & fam) - _rate(r, obey & ~fam)

# name: power_of_two_member_yes
# description: In >=2-example sets whose examples are all powers of 2 (2..64) and not all members of a smaller powers-of-m rule (m=4,8), yes rate for non-example power-of-2 targets; observed above null means people favour the powers-of-2 rule more than the family-only prior (equal weight for all powers-of-m rules) allows, below means less.

def _sets(df):
    """Per row: tuple of examples (shown order). Parsed once per unique set."""
    u = pd.unique(df["number_set"].astype(str))
    parsed = {s: tuple(int(x) for x in s.split(",")) for s in u}
    return df["number_set"].astype(str).map(parsed), parsed

def _rate(r, m):
    m = np.asarray(m, dtype=bool)
    return float(r[m].mean()) if m.any() else 0.0

FAMILIAR = set([1, 100] + [2 ** k for k in range(1, 7)] + [k * k for k in range(2, 10)] + [27] + list(range(10, 100, 10)))

def test_statistic(df):
    ex, parsed = _sets(df)
    P2 = {2, 4, 8, 16, 32, 64}
    ok = {}
    for s, e in parsed.items():
        allp = len(e) >= 2 and all(x in P2 for x in e)
        tiny = all(x in (4, 16, 64) for x in e) or all(x in (8, 64) for x in e)
        ok[s] = allp and not tiny
    t = df["target"].astype(int).to_numpy()
    r = df["rating"].astype(float).to_numpy()
    sel = df["number_set"].astype(str).map(ok).to_numpy(bool)
    nonex = np.array([tt not in e for tt, e in zip(t, ex)])
    return _rate(r, sel & nonex & np.isin(t, list(P2)))

# name: tiny_power_rule_broad_member_yes
# description: In >=2-example sets whose examples all lie in a tiny powers-of-m rule (m>=3, at most 4 members, e.g. {8,64}, {9,81}, {4,16,64}), yes rate for non-example targets that are powers of 2, powers of 3, squares or cubes but outside that tiny rule; observed above null means people generalise to the broader familiar rule more than the size principle with equal within-family priors predicts, below means less.

def _sets(df):
    """Per row: tuple of examples (shown order). Parsed once per unique set."""
    u = pd.unique(df["number_set"].astype(str))
    parsed = {s: tuple(int(x) for x in s.split(",")) for s in u}
    return df["number_set"].astype(str).map(parsed), parsed

def _rate(r, m):
    m = np.asarray(m, dtype=bool)
    return float(r[m].mean()) if m.any() else 0.0

FAMILIAR = set([1, 100] + [2 ** k for k in range(1, 7)] + [k * k for k in range(2, 10)] + [27] + list(range(10, 100, 10)))

def test_statistic(df):
    ex, parsed = _sets(df)
    tiny = [set(m ** k for k in range(1, 8) if m ** k <= 100) for m in range(3, 11)]
    broad = set([2 ** k for k in range(1, 7)] + [3 ** k for k in range(1, 5)] + [k * k for k in range(1, 11)] + [k ** 3 for k in range(1, 5)])
    rule = {}
    for s, e in parsed.items():
        rule[s] = None
        if len(e) >= 2:
            for T in tiny:
                if all(x in T for x in e):
                    rule[s] = T
                    break
    t = df["target"].astype(int).to_numpy()
    r = df["rating"].astype(float).to_numpy()
    rr = df["number_set"].astype(str).map(rule).to_numpy()
    m = np.array([(T is not None) and (tt in broad) and (tt not in T) and (tt not in e) for tt, T, e in zip(t, rr, ex)])
    return _rate(r, m)

# name: even_parity_only_yes
# description: In >=2-example sets whose examples are all even and do not all share a final digit, yes rate for non-example even targets that are NOT multiples of the examples' gcd (when gcd>2) -- i.e. supported only by the 'even' rule or ranges; observed above null means people use the parity rule more than the model predicts, below means less.

def _sets(df):
    """Per row: tuple of examples (shown order). Parsed once per unique set."""
    u = pd.unique(df["number_set"].astype(str))
    parsed = {s: tuple(int(x) for x in s.split(",")) for s in u}
    return df["number_set"].astype(str).map(parsed), parsed

def _rate(r, m):
    m = np.asarray(m, dtype=bool)
    return float(r[m].mean()) if m.any() else 0.0

FAMILIAR = set([1, 100] + [2 ** k for k in range(1, 7)] + [k * k for k in range(2, 10)] + [27] + list(range(10, 100, 10)))

def test_statistic(df):
    ex, parsed = _sets(df)
    g = {}
    for s, e in parsed.items():
        ok = len(e) >= 2 and all(x % 2 == 0 for x in e) and len(set(x % 10 for x in e)) > 1
        g[s] = math.gcd(*e) if ok else 0
    t = df["target"].astype(int).to_numpy()
    r = df["rating"].astype(float).to_numpy()
    gg = df["number_set"].astype(str).map(g).to_numpy(int)
    nonex = np.array([tt not in e for tt, e in zip(t, ex)])
    cover = (gg > 2) & (t % np.maximum(gg, 1) == 0)
    return _rate(r, (gg > 0) & nonex & (t % 2 == 0) & ~cover)
